    G["geometry.proto"]
    P["paint.proto"]
    PR["property.proto"]
    VP["vector_path.proto"]
    BS["brush_stroke.proto"]
    EM["erase_mask.proto"]
    RT["rich_text.proto"]
    CN["connector.proto"]
