# 6. Proto Source Baseline — Headers / Imports
每个 file 都从以下固定 header 开始：
```protobuf
edition = "2024";
package auditoryworks.axiom.v1;
```
不在 V1 proto source 中加入 Product RPC `service`、protobuf `Any`、protobuf `map<>`、Skia/backend type、Data Runtime persistence metadata、Bridge API。Public Runtime / DataBridge 仍然只传 opaque bytes。
<callout icon="🧭" color="yellow_bg">
	**Schema organization 与 semantic ownership 是一一映射关系，但 file boundary 不等于 runtime module boundary。** 例如 `brush_stroke.proto` 只是 wire DTO ownership；Brush Engine 仍是 Axiom runtime capability，不因 proto file 而变成独立 ABI module。
</callout>
# 7. Proto Source Baseline — Leaf / Value Files
以下 code block 是 V1 baseline 的 **normative source shape**。Semantic validation 仍以对应 Leaf Schema 为 authority。
## 7.1 `common.proto`
```protobuf
edition = "2024";
package auditoryworks.axiom.v1;

message Id128 {
  bytes value = 1;
}

message OrderKey {
  bytes value = 1;
}
```
## 7.2 `geometry.proto`
```protobuf
edition = "2024";
package auditoryworks.axiom.v1;

message Vec2 {
  double x = 1;
  double y = 2;
}
message Rect2 {
  double x = 1;
  double y = 2;
  double width = 3;
  double height = 4;
}
message NormalizedRect {
  double x = 1;
  double y = 2;
  double width = 3;
  double height = 4;
}
message Transform2D {
  double a = 1;
  double b = 2;
  double c = 3;
  double d = 4;
  double tx = 5;
  double ty = 6;
}
```
## 7.3 `paint.proto`
```protobuf
edition = "2024";
package auditoryworks.axiom.v1;

message ColorValue {
  float r = 1;
  float g = 2;
  float b = 3;
  float a = 4;
}

message NoFill {}
message SolidFill { ColorValue color = 1; }
message FillStyleValue {
  oneof value {
    NoFill none = 1;
    SolidFill solid = 2;
  }
}

message NoStroke {}
message SolidStroke {
  ColorValue color = 1;
  double width = 2;
  StrokeCap cap = 3;
  StrokeJoin join = 4;
  StrokeDash dash = 5;
}
message StrokeStyleValue {
  oneof value {
    NoStroke none = 1;
    SolidStroke solid = 2;
  }
}

enum StrokeCap {
  STROKE_CAP_INVALID = 0;
  STROKE_CAP_BUTT = 1;
  STROKE_CAP_ROUND = 2;
  STROKE_CAP_SQUARE = 3;
}

message MiterJoin { double limit = 1; }
message RoundJoin {}
message BevelJoin {}
message StrokeJoin {
  oneof value {
    MiterJoin miter = 1;
    RoundJoin round = 2;
    BevelJoin bevel = 3;
  }
}

message SolidDash {}
message DashPattern {
  repeated double segments = 1 [features.repeated_field_encoding = PACKED];
  double offset = 2;
}
message StrokeDash {
  oneof value {
    SolidDash solid = 1;
    DashPattern pattern = 2;
  }
}

enum BlendModeValue {
  BLEND_MODE_INVALID = 0;
  BLEND_MODE_NORMAL = 1;
}
enum ConnectorDecorationValue {
  CONNECTOR_DECORATION_INVALID = 0;
  CONNECTOR_DECORATION_NONE = 1;
  CONNECTOR_DECORATION_ARROW = 2;
}
```
`DashPattern.segments` 是当前唯一 repeated primitive field，V1 显式写 `PACKED`，不只依赖 Edition default，方便 canonical byte review。以后新增 repeated primitive 必须同样显式声明 canonical encoding。
## 7.4 `property.proto`
```protobuf
edition = "2024";
package auditoryworks.axiom.v1;

import "auditoryworks/axiom/v1/paint.proto";

enum PropertyValueKind {
  PROPERTY_VALUE_INVALID = 0;
  PROPERTY_VALUE_BOOL = 1;
  PROPERTY_VALUE_F32 = 2;
  PROPERTY_VALUE_COLOR = 3;
  PROPERTY_VALUE_FILL_STYLE = 4;
  PROPERTY_VALUE_STROKE_STYLE = 5;
  PROPERTY_VALUE_BLEND_MODE = 6;
  PROPERTY_VALUE_CONNECTOR_DECORATION = 7;
}

message PropertyValue {
  oneof value {
    bool bool_value = 1;
    float f32_value = 2;
    ColorValue color_value = 3;
    FillStyleValue fill_style = 4;
    StrokeStyleValue stroke_style = 5;
    BlendModeValue blend_mode = 6;
    ConnectorDecorationValue connector_decoration = 7;
  }
}
message PropertyEntry {
  uint32 field_id = 1;
  PropertyValue value = 2;
}
message PropertyBag {
  repeated PropertyEntry entries = 1;
}
```
## 7.5 `vector_path.proto`
```protobuf
edition = "2024";
package auditoryworks.axiom.v1;

import "auditoryworks/axiom/v1/geometry.proto";

enum FillRule {
  FILL_RULE_INVALID = 0;
  FILL_RULE_NON_ZERO = 1;
  FILL_RULE_EVEN_ODD = 2;
}
