  Vec2 center = 1;
  double size = 2;
  float rotation = 3;
  float opacity = 4;
}
message DabStrokeData {
  repeated DabInstance dabs = 1;
}
message StrokeRecord {
  BrushDescriptor brush = 1;
  fixed64 deterministic_seed = 2;
  oneof data {
    VectorStrokeData vector = 3;
    DabStrokeData dab = 4;
  }
}
message VectorStrokeContent { StrokeRecord stroke = 1; }
message DabStrokeContent { StrokeRecord stroke = 1; }
```
<callout icon="✅" color="green_bg">
	Brush downstream semantic已完成 RC-B06/B07/B08 Proposed Freeze：BrushFamily = `1 FinePen / 2 Highlighter / 3 TexturedMarker`；PRNG/Highlighter由 <mention-page url="https://app.notion.com/p/3c54c57a590c81ffa7c5c6080fe940d4"/> 冻结；Pressure/Tilt由 <mention-page url="https://app.notion.com/p/3c54c57a590c81d4a46ff149c10ceadd"/> 冻结。`StrokeSample.tilt` tag 3仍保留在 proto，但对当前 V1 family semantic-invalid when present；`PressureMapping/TiltMapping` 的 disabled form依赖 Edition explicit presence。上述 closure不产生新的 descriptor structural diff。
</callout>
## 7.7 `erase_mask.proto`
```protobuf
edition = "2024";
package auditoryworks.axiom.v1;

import "auditoryworks/axiom/v1/common.proto";
import "auditoryworks/axiom/v1/geometry.proto";
import "auditoryworks/axiom/v1/vector_path.proto";

