  repeated EraseCubicSegment segments = 1;
}
message FilledPathMask {
  VectorPathGeometry path = 1;
}
message EraseMaskGeometry {
  oneof geometry {
    SweptCircleMask swept_circle = 1;
    FilledPathMask filled_path = 2;
  }
}
