  Id128 mask_id = 1;
  EraseMaskGeometry geometry = 2;
}
```
## 7.8 `rich_text.proto`
```protobuf
edition = "2024";
package auditoryworks.axiom.v1;

import "auditoryworks/axiom/v1/common.proto";
import "auditoryworks/axiom/v1/paint.proto";

message TextStyle {
  Id128 font_resource_id = 1;
  double font_size = 2;
  uint32 weight = 3;
  bool italic = 4;
  bool underline = 5;
  ColorValue color = 6;
}
enum ParagraphAlignment {
  PARAGRAPH_ALIGNMENT_INVALID = 0;
  PARAGRAPH_ALIGNMENT_LEFT = 1;
  PARAGRAPH_ALIGNMENT_CENTER = 2;
  PARAGRAPH_ALIGNMENT_RIGHT = 3;
  PARAGRAPH_ALIGNMENT_JUSTIFY = 4;
}
message ParagraphStyle {
  ParagraphAlignment alignment = 1;
  double line_height = 2;
  double spacing_before = 3;
  double spacing_after = 4;
}
message TextRun {
  string text = 1;
  TextStyle style = 2;
}
message Paragraph {
  Id128 paragraph_id = 1;
  ParagraphStyle style = 2;
  repeated TextRun runs = 3;
}
message RichTextDocument {
  repeated Paragraph paragraphs = 1;
}
message RichTextContent {
  RichTextDocument document = 1;
}

message InsertTextStep {
  Id128 paragraph_id = 1;
  uint32 scalar_offset = 2;
  string text = 3;
  TextStyle style = 4;
}
message DeleteTextStep {
  Id128 paragraph_id = 1;
  uint32 start_scalar = 2;
  uint32 scalar_count = 3;
}
message SplitParagraphStep {
